    public List<List<Rate>> rateChain(String sheetId, LocalDate asOf) {
        List<List<Rate>> chain = new ArrayList<>();
        chain.add(withOlder(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId)));
